script:
(function () {
  'use strict';
  // Adjustable-rate mortgage (ARM) payment projection.
  //   Payment at any rate: M = B * i / (1 - (1 + i)^-n), i = rate / 12, n = months left (M = B / n at 0%).
  //   The rate is fixed for the initial period, then changes by the expected amount at every
  //   adjustment, limited by the first-adjustment cap, the periodic cap, the lifetime cap (initial
  //   rate + cap) and the floor. At each adjustment the payment is re-amortized over the months left.
  //   Worst case = the rate rises by the full cap at every adjustment until the lifetime cap.
  // Verified in Node (scratchpad tests/w2b): $300,000 at 6% for 30 yrs = $1,798.65/mo; balance after
  //   60 payments $279,163.07 (closed form); a 5/1 ARM rising 0.25% a year re-amortizes to $1,841.55
  //   at 6.25% from payment 61 (closed form on the remaining balance over 300 months); with a 0% change it matches the
  //   fixed loan exactly (total interest $347,514.57); worst case with 2/2/5 caps reaches 11% in year 8;
  //   0% rate = $833.33/mo; final balance is 0; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  function pct(v) { return (Math.round(v * 1000) / 1000) + '%'; }

  // o: loan, months, rate (%), fixedMonths, every, change (% per adjustment), firstCap, periodicCap, lifeCap, floor
  function schedule(o) {
    var rate = o.rate, maxRate = o.rate + o.lifeCap, minRate = Math.min(o.floor, o.rate);
    var bal = o.loan, pay = payment(bal, rate, o.months), rows = [], adj = 0, totalInterest = 0;
    var maxPay = pay, maxPayMonth = 1, firstAdjPay = null, maxRateSeen = rate;
    for (var m = 1; m <= o.months && bal > 0.005; m++) {
      if (m > o.fixedMonths && (m - o.fixedMonths - 1) % o.every === 0) {
        var cap = adj === 0 ? o.firstCap : o.periodicCap;
        var step = Math.max(-cap, Math.min(cap, o.change));
        rate = Math.max(minRate, Math.min(maxRate, rate + step));
        rate = Math.round(rate * 100000) / 100000;
        pay = payment(bal, rate, o.months - m + 1);
        if (adj === 0) firstAdjPay = pay;
        adj++;
        if (pay > maxPay + 0.005) { maxPay = pay; maxPayMonth = m; }
        if (rate > maxRateSeen) maxRateSeen = rate;
      }
      var interest = bal * rate / 1200;
      var principal = Math.min(pay - interest, bal);
      if (m === o.months) principal = bal;
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      rows.push({ n: m, rate: rate, payment: principal + interest, interest: interest, principal: principal, balance: bal });
    }
    return { first: payment(o.loan, o.rate, o.months), firstAdjPay: firstAdjPay, maxPay: maxPay, maxPayMonth: maxPayMonth,
             maxRate: maxRateSeen, totalInterest: totalInterest, rows: rows };
  }

  function when(month) {
    var y = Math.floor((month - 1) / 12) + 1, mo = (month - 1) % 12 + 1;
    return 'year ' + y + ', month ' + mo;
  }

  function clearResults() {
    ['arFirstPay', 'arAdjPay', 'arMaxPay', 'arTotalInterest', 'arMaxPayWhen', 'arTotalPaid', 'arPeakRate',
     'arWorstRate', 'arWorstPay', 'arWorstWhen', 'arWorstInterest'].forEach(function (id) { setText(id, '–'); });
    el('arSchedule').innerHTML = '';
  }

  function update() {
    var loan = read('arLoan'), years = read('arTerm'), rate = read('arRate'), fixedYears = read('arFixed'),
        every = parseInt(el('arEvery').value, 10), change = read('arChange'), firstCap = read('arFirstCap'),
        periodicCap = read('arPeriodicCap'), lifeCap = read('arLifeCap'), floor = read('arFloor');
    var msg = '';
    if (isNaN(loan) || loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(years) || years < 1 || years > 40 || years % 1 !== 0) msg = 'Enter a loan term of 1 to 40 whole years.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an initial interest rate from 0% to 30%.';
    else if (isNaN(fixedYears) || fixedYears < 1 || fixedYears % 1 !== 0 || fixedYears >= years) msg = 'Enter a fixed-rate period of at least 1 whole year that is shorter than the loan term.';
    else if (isNaN(change) || change < -5 || change > 5) msg = 'Enter an expected change per adjustment from -5% to 5%.';
    else if ([firstCap, periodicCap, lifeCap].some(function (v) { return isNaN(v) || v < 0 || v > 15; })) msg = 'Enter rate caps from 0% to 15%.';
    else if (isNaN(floor) || floor < 0 || floor > 30) msg = 'Enter a rate floor from 0% to 30%.';
    var error = el('arError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var o = { loan: loan, months: years * 12, rate: rate, fixedMonths: fixedYears * 12, every: every, change: change,
              firstCap: firstCap, periodicCap: periodicCap, lifeCap: lifeCap, floor: floor };
    var r = schedule(o);
    var w = schedule({ loan: loan, months: o.months, rate: rate, fixedMonths: o.fixedMonths, every: every, change: 100,
                       firstCap: firstCap, periodicCap: periodicCap, lifeCap: lifeCap, floor: floor });

    setText('arFirstPay', money.format(r.first));
    setText('arAdjPay', r.firstAdjPay === null ? '–' : money.format(r.firstAdjPay));
    setText('arMaxPay', money.format(r.maxPay));
    setText('arMaxPayWhen', r.maxPay > r.first + 0.005 ? when(r.maxPayMonth) : 'Never above the first payment');
    setText('arTotalInterest', money.format(r.totalInterest));
    setText('arTotalPaid', money.format(loan + r.totalInterest));
    setText('arPeakRate', pct(r.maxRate));
    setText('arWorstRate', pct(rate + lifeCap));
    setText('arWorstPay', money.format(w.maxPay));
    setText('arWorstWhen', w.maxPay > w.first + 0.005 ? when(w.maxPayMonth) : 'Never above the first payment');
    setText('arWorstInterest', money.format(w.totalInterest));

    var html = [], p = 0, intr = 0;
    r.rows.forEach(function (row, idx) {
      p += row.principal; intr += row.interest;
      if (row.n % 12 === 0 || idx === r.rows.length - 1) {
        html.push('<tr><td>' + Math.ceil(row.n / 12) + '</td><td>' + pct(row.rate) + '</td><td>' + money.format(row.payment) +
          '</td><td>' + money.format(p) + '</td><td>' + money.format(intr) + '</td><td>' + money.format(row.balance) + '</td></tr>');
        p = 0; intr = 0;
      }
    });
    el('arSchedule').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('arForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
